mapper.select:
SELECT * FROM gb_ai_daily_revenue
WHERE 1=1

	AND gb_ai_daily_revenue_parent_department_id IN

		#{sid}




		AND gb_ai_daily_revenue_parent_department_id = #{departmentId}



	AND gb_ai_daily_revenue_record_date >= #{startDate}


	AND gb_ai_daily_revenue_record_date <= #{endDate}

ORDER BY gb_ai_daily_revenue_record_date ASC

SELECT COUNT(*) as days, COALESCE(AVG(day_gross), 0) as avg_daily_revenue, COALESCE(SUM(day_gross), 0) as total_revenue, COALESCE(SUM(day_orders), 0) as total_orders, COALESCE(AVG(day_orders), 0) as avg_order_count, COALESCE(AVG((day_dine_in + day_takeout) / NULLIF((day_dine_cust + day_takeout_ord), 0)), 0) as avg_per_customer, COALESCE(SUM(day_platform), 0) as total_coupon_amount, COALESCE(SUM(day_platform), 0) as total_platform_fee, COALESCE(SUM(day_dine_in), 0) as total_dine_in_revenue, COALESCE(AVG(day_dine_in), 0) as avg_dine_in_revenue, 0 as total_refund_amount, COALESCE(MAX(day_gross), 0) as max_daily_revenue, COALESCE(MIN(day_gross), 0) as min_daily_revenue, COALESCE(SUM(day_takeout), 0) as total_takeout_revenue, COALESCE(AVG(day_takeout), 0) as avg_takeout_revenue, COALESCE(SUM(day_takeout_net), 0) as total_takeout_net, COALESCE(AVG(day_takeout_net), 0) as avg_takeout_net FROM ( SELECT gb_ai_daily_revenue_record_date, COALESCE(SUM(COALESCE(gb_ai_daily_revenue_dine_in_revenue, 0) + COALESCE(gb_ai_daily_revenue_takeout_revenue, 0)), 0) AS day_gross, COALESCE(SUM(gb_ai_daily_revenue_dine_in_revenue), 0) AS day_dine_in, COALESCE(SUM(gb_ai_daily_revenue_takeout_revenue), 0) AS day_takeout, COALESCE(SUM(COALESCE(gb_ai_daily_revenue_dine_in_orders, 0) + COALESCE(gb_ai_daily_revenue_takeout_orders, 0)), 0) AS day_orders, COALESCE(SUM(gb_ai_daily_revenue_dine_in_customers), 0) AS day_dine_cust, COALESCE(SUM(gb_ai_daily_revenue_takeout_orders), 0) AS day_takeout_ord, COALESCE(SUM(gb_ai_daily_revenue_platform_fee), 0) AS day_platform, COALESCE(SUM(gb_ai_daily_revenue_takeout_revenue), 0) - COALESCE(SUM(gb_ai_daily_revenue_platform_fee), 0) AS day_takeout_net FROM gb_ai_daily_revenue WHERE gb_ai_daily_revenue_parent_department_id IN
#{sid}
AND gb_ai_daily_revenue_record_date >= #{params.startDate}
AND gb_ai_daily_revenue_record_date <= #{params.endDate}
GROUP BY gb_ai_daily_revenue_record_date ) daily

SELECT COALESCE(SUM(
	COALESCE(gb_ai_daily_revenue_dine_in_revenue, 0)
	+ COALESCE(gb_ai_daily_revenue_takeout_revenue, 0)
	- COALESCE(gb_ai_daily_revenue_platform_fee, 0)
), 0)
FROM gb_ai_daily_revenue
WHERE gb_ai_daily_revenue_parent_department_id IN

	#{did}

AND gb_ai_daily_revenue_record_date >= #{startDate}
AND gb_ai_daily_revenue_record_date <= #{endDate}

SELECT COALESCE(SUM(COALESCE(gb_ai_daily_revenue_dine_in_revenue, 0)), 0) AS totalDineIn, COALESCE(SUM(COALESCE(gb_ai_daily_revenue_takeout_revenue, 0)), 0) AS totalTakeout, COALESCE(SUM(COALESCE(gb_ai_daily_revenue_platform_fee, 0)), 0) AS totalPlatformFee, COUNT(*) AS revenueRowCount, COUNT(DISTINCT gb_ai_daily_revenue_record_date) AS distinctRecordDates, MIN(gb_ai_daily_revenue_record_date) AS minRecordDate, MAX(gb_ai_daily_revenue_record_date) AS maxRecordDate FROM gb_ai_daily_revenue WHERE gb_ai_daily_revenue_parent_department_id IN
#{did}
AND gb_ai_daily_revenue_record_date >= #{startDate} AND gb_ai_daily_revenue_record_date <= #{endDate}

SELECT COALESCE(SUM(
	COALESCE(gb_ai_daily_revenue_dine_in_revenue, 0)
	+ COALESCE(gb_ai_daily_revenue_takeout_revenue, 0)
	- COALESCE(gb_ai_daily_revenue_platform_fee, 0)
), 0)
FROM gb_ai_daily_revenue
WHERE gb_ai_daily_revenue_distributer_id = #{distributerId}
AND gb_ai_daily_revenue_record_date >= #{startDate}
AND gb_ai_daily_revenue_record_date <= #{endDate}

SELECT gb_ai_daily_revenue_parent_department_id AS departmentId,
	'' AS departmentName,
	COALESCE(SUM(
		COALESCE(gb_ai_daily_revenue_dine_in_revenue, 0)
		+ COALESCE(gb_ai_daily_revenue_takeout_revenue, 0)
		- COALESCE(gb_ai_daily_revenue_platform_fee, 0)
	), 0) AS netRevenue
FROM gb_ai_daily_revenue
WHERE gb_ai_daily_revenue_parent_department_id IN

	#{did}

AND gb_ai_daily_revenue_record_date >= #{startDate}
AND gb_ai_daily_revenue_record_date <= #{endDate}
GROUP BY gb_ai_daily_revenue_parent_department_id

SELECT
	COALESCE(SUM(COALESCE(dr.gb_ai_daily_revenue_dine_in_revenue, 0)
		+ COALESCE(dr.gb_ai_daily_revenue_takeout_revenue, 0)), 0) AS totalGrossRevenue,
	COALESCE(SUM(COALESCE(dr.gb_ai_daily_revenue_dine_in_orders, 0)
		+ COALESCE(dr.gb_ai_daily_revenue_takeout_orders, 0)), 0) AS totalOrders,
	COALESCE(SUM(COALESCE(dr.gb_ai_daily_revenue_platform_fee, 0)), 0) AS totalPlatformFee,
	COALESCE(SUM(COALESCE(dr.gb_ai_daily_revenue_dine_in_revenue, 0)), 0) AS totalDineIn,
	COALESCE(SUM(COALESCE(dr.gb_ai_daily_revenue_takeout_revenue, 0)), 0) AS totalTakeout,
	COALESCE(SUM(
		COALESCE(dr.gb_ai_daily_revenue_takeout_revenue, 0)
		- COALESCE(dr.gb_ai_daily_revenue_platform_fee, 0)
	), 0) AS totalTakeoutNetApprox,
	COUNT(DISTINCT dr.gb_ai_daily_revenue_record_date) AS distinctRecordDates,
	COUNT(DISTINCT dr.gb_ai_daily_revenue_parent_department_id) AS distinctRecordingDepartments,
	COALESCE((
		SELECT MAX(agg.day_gross) FROM (
			SELECT SUM(COALESCE(dx.gb_ai_daily_revenue_dine_in_revenue, 0)
				+ COALESCE(dx.gb_ai_daily_revenue_takeout_revenue, 0)) AS day_gross
			FROM gb_ai_daily_revenue dx
			WHERE dx.gb_ai_daily_revenue_parent_department_id IN

				#{did}

			AND dx.gb_ai_daily_revenue_record_date >= #{startDate}
			AND dx.gb_ai_daily_revenue_record_date <= #{endDate}
			GROUP BY dx.gb_ai_daily_revenue_record_date
		) agg
	), 0) AS maxDailyGross,
	COALESCE((
		SELECT MIN(agg2.day_gross) FROM (
			SELECT SUM(COALESCE(dy.gb_ai_daily_revenue_dine_in_revenue, 0)
				+ COALESCE(dy.gb_ai_daily_revenue_takeout_revenue, 0)) AS day_gross
			FROM gb_ai_daily_revenue dy
			WHERE dy.gb_ai_daily_revenue_parent_department_id IN

				#{did}

			AND dy.gb_ai_daily_revenue_record_date >= #{startDate}
			AND dy.gb_ai_daily_revenue_record_date <= #{endDate}
			GROUP BY dy.gb_ai_daily_revenue_record_date
			HAVING SUM(COALESCE(dy.gb_ai_daily_revenue_dine_in_revenue, 0)
				+ COALESCE(dy.gb_ai_daily_revenue_takeout_revenue, 0)) > 0
		) agg2
	), 0) AS minDailyGrossPositive
FROM gb_ai_daily_revenue dr
WHERE dr.gb_ai_daily_revenue_parent_department_id IN

	#{did}

AND dr.gb_ai_daily_revenue_record_date >= #{startDate}
AND dr.gb_ai_daily_revenue_record_date <= #{endDate}

SELECT DISTINCT dr.gb_ai_daily_revenue_parent_department_id
FROM gb_ai_daily_revenue dr
WHERE dr.gb_ai_daily_revenue_parent_department_id IN

	#{did}

AND dr.gb_ai_daily_revenue_record_date >= #{startDate}
AND dr.gb_ai_daily_revenue_record_date <= #{endDate}

SELECT dr.gb_ai_daily_revenue_parent_department_id AS departmentId, COALESCE(SUM(COALESCE(dr.gb_ai_daily_revenue_dine_in_revenue, 0) + COALESCE(dr.gb_ai_daily_revenue_takeout_revenue, 0)), 0) AS grossRevenue, COALESCE(SUM(COALESCE(dr.gb_ai_daily_revenue_dine_in_orders, 0) + COALESCE(dr.gb_ai_daily_revenue_takeout_orders, 0)), 0) AS totalOrders, CAST(COUNT(DISTINCT dr.gb_ai_daily_revenue_record_date) AS SIGNED INTEGER) AS distinctRecordDates, COALESCE(SUM(COALESCE(dr.gb_ai_daily_revenue_takeout_revenue, 0)), 0) AS takeoutRevenue, COALESCE(SUM(COALESCE(dr.gb_ai_daily_revenue_platform_fee, 0)), 0) AS platformFee FROM gb_ai_daily_revenue dr WHERE dr.gb_ai_daily_revenue_parent_department_id IN
#{did}
AND dr.gb_ai_daily_revenue_record_date >= #{startDate} AND dr.gb_ai_daily_revenue_record_date <= #{endDate} GROUP BY dr.gb_ai_daily_revenue_parent_department_id
